code="from flask import Flask\nimport os, threading, time, requests, pytz\nfrom datetime import datetime\napp=Flask(__name__)\nTELEGRAM_BOT_TOKEN=os.environ.get('TELEGRAM_BOT_TOKEN')\nTELEGRAM_CHAT_ID=os.environ.get('TELEGRAM_CHAT_ID')\ndef send_tg(msg):\n    print(f'TOKEN EXISTS: {bool(TELEGRAM_BOT_TOKEN)} CHAT EXISTS: {bool(TELEGRAM_CHAT_ID)}')\n    try:\n        if TELEGRAM_BOT_TOKEN and TELEGRAM_CHAT_ID:\n            r=requests.post(f'https://api.telegram.org/bot{TELEGRAM_BOT_TOKEN}/sendMessage', json={'chat_id': TELEGRAM_CHAT_ID, 'text': msg}, timeout=10)\n            print(f'TG Response: {r.text}')\n        else:\n            print('MISSING TOKEN OR CHAT ID IN ENV')\n    except Exception as e:\n        print(f'TG Error: {e}')\ndef trading_loop():\n    send_tg('Ross Bot TEST - If you get this, Telegram works!')\n    while True:\n        time.sleep(60)\napp.add_url_rule('/', 'home', lambda: 'Ross Bot Diagnostic LIVE')\napp.add_url_rule('/health', 'health', lambda: 'OK')\nif __name__=='__main__':\n    threading.Thread(target=trading_loop, daemon=True).start()\n    app.run(host='0.0.0.0', port=int(os.environ.get('PORT', 10000)))\n"
exec(code)
